  ('layer','TS','Topsoil',5,'{}','Tanah pucuk / topsoil'),
  ('layer','TRN','Transisi',25,'{}','Zona transisi antara limonit dan saprolit'),
  ('activity','TIME_TRIP','Time Trip',50,'{}','Waktu trip rod / peralatan'),
