-- ======================================================================
-- FILE: 0011_map_class_coh.sql
-- ======================================================================
-- 0011: map class "Progress" is removed. COH = continuation of hole (drilling). Run per site; safe to run twice.
update public.exp_code_list set meta = meta || '{"map_class":"coh"}'::jsonb
 where list_code = 'collar_status' and meta->>'map_class' = 'progress';
-- abandoned used to show as COH; an abandoned hole is finished, so show it as EOH (change in Pengaturan if the site wants otherwise)
update public.exp_code_list set meta = meta || '{"map_class":"eoh"}'::jsonb
 where list_code = 'collar_status' and code = 'abandoned' and meta->>'map_class' = 'coh';

-- ======================================================================
-- FILE: 0012_input_forms.sql
-- ======================================================================
-- 0012: per-form input permission.
-- A role with can_write may input every form. A user can be limited to some forms:
--   exp_profile.input_forms = NULL                   -> all forms the role allows
--   exp_profile.input_forms = '{progress,collar}'    -> only those forms
-- Forms: progress (exp_drill_progress), collar (exp_collar + exp_survey), hours (exp_dist_hour), sample (exp_sample + exp_assay).
-- Reading is unchanged (any active role reads everything). Run per site, safe to re-run.

alter table public.exp_profile add column if not exists input_forms text[];
alter table public.exp_profile drop constraint if exists exp_profile_input_forms_chk;
alter table public.exp_profile add constraint exp_profile_input_forms_chk
  check (input_forms is null or input_forms <@ array['progress','collar','hours','sample']::text[]);

create or replace function public.exp_can_input(p_form text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select d.can_write and (p.input_forms is null or p_form = any(p.input_forms))
    from public.exp_profile p join public.exp_role_def d on d.role = p.role
    where p.user_id = auth.uid() and p.is_active and d.is_active), false)
$$;
grant execute on function public.exp_can_input(text) to authenticated;

-- table policies: write = may input that form
do $$
declare t text; f text;
begin
  for t, f in select * from (values
    ('exp_collar','collar'), ('exp_survey','collar'), ('exp_drill_progress','progress'),
    ('exp_dist_hour','hours'), ('exp_sample','sample'), ('exp_assay','sample')) v(tbl, frm)
  loop
    execute format('drop policy if exists %I on public.%I', t||'_ins', t);
    execute format('drop policy if exists %I on public.%I', t||'_upd', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (public.exp_can_input(%L))', t||'_ins', t, f);
    execute format('create policy %I on public.%I for update to authenticated using (public.exp_can_input(%L)) with check (public.exp_can_input(%L))', t||'_upd', t, f, f);
  end loop;
end $$;

-- photos: collar/ needs the collar form, core/ needs the progress form
drop policy if exists exp_photos_ins on storage.objects;
create policy exp_photos_ins on storage.objects for insert to authenticated
  with check (bucket_id = 'exp-photos' and (
    (name like 'collar/%' and public.exp_can_input('collar')) or (name like 'core/%' and public.exp_can_input('progress'))));
drop policy if exists exp_photos_upd on storage.objects;
create policy exp_photos_upd on storage.objects for update to authenticated
  using (bucket_id = 'exp-photos' and (
    (name like 'collar/%' and public.exp_can_input('collar')) or (name like 'core/%' and public.exp_can_input('progress'))));

-- admin RPC: p_forms = NULL (all) or the allowed forms. Only meaningful for roles with can_write.
drop function if exists public.exp_admin_upsert_profile(text, text, text, boolean);
create or replace function public.exp_admin_upsert_profile(
  p_email text, p_name text, p_role text, p_active boolean default true, p_forms text[] default null)
returns void language plpgsql security definer set search_path = public, auth as $$
declare uid uuid; target_super boolean; current_super boolean; writer boolean;
begin
  if not public.exp_can_admin() then raise exception 'Not allowed'; end if;
  if not exists (select 1 from public.exp_role_def where role = p_role and is_active) then
    raise exception 'Role % tidak ada atau tidak aktif.', p_role;
  end if;
  select id into uid from auth.users where lower(email) = lower(trim(p_email));
  if uid is null then
    raise exception 'No Auth user with email %. Create the user in Supabase Auth first (or ask a super admin to add the user).', p_email;
  end if;
  select coalesce(can_super, false), coalesce(can_write, false) into target_super, writer from public.exp_role_def where role = p_role;
  select coalesce(d.can_super, false) into current_super from public.exp_profile p join public.exp_role_def d on d.role = p.role where p.user_id = uid;
  if (target_super or coalesce(current_super, false)) and not public.exp_is_super() then
    raise exception 'Hanya super admin yang boleh menetapkan atau mengubah akun super admin.';
  end if;
  insert into public.exp_profile (user_id, full_name, role, is_active, email, input_forms)
  values (uid, trim(p_name), p_role, p_active, lower(trim(p_email)), case when writer then p_forms else null end)
  on conflict (user_id) do update
    set full_name = excluded.full_name, role = excluded.role, is_active = excluded.is_active, email = excluded.email,
        input_forms = case when writer then excluded.input_forms else null end;
end $$;
revoke all on function public.exp_admin_upsert_profile(text, text, text, boolean, text[]) from public, anon;
grant execute on function public.exp_admin_upsert_profile(text, text, text, boolean, text[]) to authenticated;

-- ======================================================================
-- FILE: 0013_consumables_and_cleanup.sql
-- ======================================================================
-- ============================================================================
-- 0013: consumables move to Distribution Hour + drop what the app no longer uses.
-- Run once per site, after 0012. Safe to run twice. Does not touch the hub (supabase/hub/*).
--
-- 1. exp_dist_hour gets fuel_l, polymer_l, oil_hyd_l (per rig entry, optional).
--    exp_drill_progress loses the same three columns (the app never filled them on that form).
--    The run STOPS, changing nothing, if any Progress row still holds a consumables value:
--    export those rows first (they cannot be moved to rig entries automatically).
-- 2. hub_export keeps its contract: drill_progress still exposes fuel_l / polymer_l / oil_hyd_l
--    (always NULL now) so the hub's explicit column list keeps matching; dist_hour gets the three
--    columns appended (the hub ignores them until its own pull list is extended).
-- 3. Dropped because the app does not read them: exp_map_layer (map layers are device-only) and the
--    seven site views v_exp_* (the dashboard reads the hub, not these).
--    Kept on purpose: exp_weekly_plan (the hub pulls it), exp_iup (boundary shown on the map).
-- ============================================================================

-- 1a. new columns on rig entries
alter table public.exp_dist_hour add column if not exists fuel_l    numeric(7,1) check (fuel_l    >= 0);
alter table public.exp_dist_hour add column if not exists polymer_l numeric(7,1) check (polymer_l >= 0);
alter table public.exp_dist_hour add column if not exists oil_hyd_l numeric(7,1) check (oil_hyd_l >= 0);

-- 1b. refuse to drop consumables that hold data
do $$
declare n bigint;
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'exp_drill_progress' and column_name = 'fuel_l') then
    execute 'select count(*) from public.exp_drill_progress where fuel_l is not null or polymer_l is not null or oil_hyd_l is not null' into n;
    if n > 0 then
      raise exception '% Progress rows still hold consumables (fuel / polymer / hyd oil). Export them first (select id, work_date, rig_id, hole_id, fuel_l, polymer_l, oil_hyd_l from public.exp_drill_progress where fuel_l is not null or polymer_l is not null or oil_hyd_l is not null), then run again. Nothing was changed.', n;
    end if;
  end if;
end $$;

-- 2. hub export views first (they depend on the columns being dropped)
do $exp$
begin
  if to_regnamespace('hub_export') is null or not exists (select 1 from pg_roles where rolname = 'hub_reader') then
    raise notice 'hub_export / hub_reader not found: export views skipped.';
    return;
  end if;
  create or replace view hub_export.drill_progress as
    select id, work_date, shift, rig_id, hole_id, from_m, to_m, meters,
           downtime_hours, downtime_reason, remarks, is_deleted,
           created_at, updated_at, server_updated_at,
           core_len_m, core_recovery_pct, layer,
           null::numeric(7,1) as fuel_l, null::numeric(7,1) as polymer_l, null::numeric(7,1) as oil_hyd_l
    from public.exp_drill_progress;
  create or replace view hub_export.dist_hour as
    select id, work_date, rig_id, from_time, to_time, hours, activity, remarks, is_deleted,
           created_at, updated_at, server_updated_at,
           fuel_l, polymer_l, oil_hyd_l
    from public.exp_dist_hour;
  grant select on hub_export.drill_progress, hub_export.dist_hour to hub_reader;
end
$exp$;

-- 1c. drop the old columns
alter table public.exp_drill_progress
  drop column if exists fuel_l, drop column if exists polymer_l, drop column if exists oil_hyd_l;

-- 3. objects the app does not use
drop table if exists public.exp_map_layer;
drop view if exists public.v_exp_hole_progress, public.v_exp_dist_hour_summary, public.v_exp_sample_status,
                    public.v_exp_weekly_plan_actual, public.v_exp_dq_progress_unknown_hole,
                    public.v_exp_dq_sample_unknown_hole, public.v_exp_dq_assay_unknown_hole;

-- check: select column_name from information_schema.columns where table_name = 'exp_dist_hour' and column_name in ('fuel_l','polymer_l','oil_hyd_l');

-- ======================================================================
-- FILE: 0014_lab_roa_qaqc.sql
-- ======================================================================
-- ============================================================================
-- 0014: lab Report of Analysis (RoA) import + geochemical QAQC.
-- Run once per site, after 0013. Safe to run twice. Does not touch the hub tables (supabase/hub/*).
--
-- 1. exp_assay gets lab_seq, client_ref, received_date, tested_date, reported_date
--    (all optional; filled by the RoA PDF import).
-- 2. BLANK and CRM rows have no hole and no interval, so hole_id / from_m / to_m become nullable.
--    A check keeps NORMAL and DUPLICATE rows strict: they still need a hole and a valid interval.
-- 3. exp_crm: certified values and SD per reference material and analyte (used for the Z-score).
--    Read by every active role, written by admins only. Seeded with OREAS 182b.
-- 4. exp_setting: default QAQC thresholds (key 'qaqc_thresholds', editable by admins).
-- 5. hub_export.assay: new columns appended; rows without a hole are NOT exported
--    (the hub table requires a hole). The hub's explicit column list keeps working.
-- ============================================================================

-- 1. RoA columns
alter table public.exp_assay add column if not exists lab_seq       int;
alter table public.exp_assay add column if not exists client_ref    text;
alter table public.exp_assay add column if not exists received_date date;
alter table public.exp_assay add column if not exists tested_date   date;
alter table public.exp_assay add column if not exists reported_date date;

-- 2. nullable hole / interval for QC rows, strict for the rest
alter table public.exp_assay alter column hole_id drop not null;
alter table public.exp_assay alter column from_m  drop not null;
alter table public.exp_assay alter column to_m    drop not null;

alter table public.exp_assay drop constraint if exists chk_assay_interval;
alter table public.exp_assay add  constraint chk_assay_interval
  check (to_m is null or from_m is null or to_m > from_m);

alter table public.exp_assay drop constraint if exists chk_assay_hole_fmt;
alter table public.exp_assay add  constraint chk_assay_hole_fmt
  check (hole_id is null or hole_id ~ '^[A-Z0-9-]{4,30}$');

alter table public.exp_assay drop constraint if exists chk_assay_needs_interval;
alter table public.exp_assay add  constraint chk_assay_needs_interval
  check (sample_type in ('BLANK', 'CRM') or (hole_id is not null and from_m is not null and to_m is not null));

-- the live-row key stays; rows with a NULL hole never collide in a unique index, so
-- BLANK/CRM rows are protected by sample_no + batch instead:
create unique index if not exists uq_exp_assay_qc_live
  on public.exp_assay (coalesce(batch_id, ''), sample_no)
  where not is_deleted and hole_id is null and sample_no is not null;

-- the overlap guard compares hole + interval; QC rows without a hole are skipped
create or replace function public.exp_guard_interval()
returns trigger language plpgsql as $$
declare o record;
begin
  if new.is_deleted or new.sample_type <> 'NORMAL' or new.hole_id is null then return new; end if;
  if tg_table_name = 'exp_sample' then
    select sample_no as ref, from_m, to_m into o from public.exp_sample
     where id <> new.id and not is_deleted and sample_type = 'NORMAL' and hole_id = new.hole_id
       and from_m < new.to_m and to_m > new.from_m limit 1;
  else
    select coalesce(sample_no, 'tanpa nomor') as ref, from_m, to_m into o from public.exp_assay
     where id <> new.id and not is_deleted and sample_type = 'NORMAL' and hole_id = new.hole_id
       and from_m < new.to_m and to_m > new.from_m limit 1;
  end if;
  if found then
    raise exception 'Interval % - % m overlap dengan % (% - % m) di lubang %.',
      new.from_m, new.to_m, o.ref, o.from_m, o.to_m, new.hole_id using errcode = '23P01';
  end if;
  return new;
end $$;

-- 3. certified reference materials
create table if not exists public.exp_crm (
  id              uuid primary key default gen_random_uuid(),
  crm_name        text not null,
  analyte         text not null,
  certified_value numeric(12,5) not null,
  sd              numeric(12,5) not null check (sd > 0),
  unit            text not null default '%',
  source          text,
  is_deleted      boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  server_updated_at timestamptz not null default now()
);
create unique index if not exists uq_exp_crm_live on public.exp_crm (upper(crm_name), analyte) where not is_deleted;

drop trigger if exists trg_exp_crm_2_touch on public.exp_crm;
create trigger trg_exp_crm_2_touch before insert or update on public.exp_crm
  for each row execute function public.exp_touch();

alter table public.exp_crm enable row level security;
drop policy if exists exp_crm_read on public.exp_crm;
create policy exp_crm_read on public.exp_crm for select to authenticated using (public.exp_role() is not null);
drop policy if exists exp_crm_ins on public.exp_crm;
create policy exp_crm_ins on public.exp_crm for insert to authenticated with check (public.exp_can_admin());
drop policy if exists exp_crm_upd on public.exp_crm;
create policy exp_crm_upd on public.exp_crm for update to authenticated using (public.exp_can_admin()) with check (public.exp_can_admin());

-- OREAS 182b (certificate values; Fe2O3 / MgO / SiO2 / Al2O3 / Cr2O3 are oxide %).
insert into public.exp_crm (crm_name, analyte, certified_value, sd, unit, source) values
  ('OREAS 182b', 'Ni',    0.757,  0.018,  '%', 'OREAS 182b certificate'),
  ('OREAS 182b', 'Co',    0.0809, 0.0016, '%', 'OREAS 182b certificate'),
  ('OREAS 182b', 'Fe2O3', 32.78,  0.283,  '%', 'OREAS 182b certificate'),
  ('OREAS 182b', 'MgO',   8.75,   0.149,  '%', 'OREAS 182b certificate'),
  ('OREAS 182b', 'SiO2',  32.33,  0.323,  '%', 'OREAS 182b certificate'),
  ('OREAS 182b', 'Al2O3', 6.91,   0.101,  '%', 'OREAS 182b certificate'),
  ('OREAS 182b', 'Cr2O3', 0.845,  0.012,  '%', 'OREAS 182b certificate')
on conflict do nothing;

-- 4. default thresholds (admins can edit the JSON; the app falls back to these values if the key is missing)
insert into public.exp_setting (key, value) values ('qaqc_thresholds', '{
  "blank_ni_max": 0.05,
  "dup_ard_ni_max": {"PD": 0.05, "CD": 0.10, "RD": 0.10},
  "crm_z_warn": 2,
  "crm_z_fail": 3,
  "fe2o3_tol_pct": 3,
  "mc_max": 45,
  "cutoff_ni": 0.8
}'::jsonb) on conflict (key) do nothing;

-- 5. hub export: append columns, hide hole-less QC rows (the hub requires a hole)
do $exp$
begin
  if to_regnamespace('hub_export') is null or not exists (select 1 from pg_roles where rolname = 'hub_reader') then
    raise notice 'hub_export / hub_reader not found: export view skipped.';
    return;
  end if;
  create or replace view hub_export.assay as
    select id, hole_id, from_m, to_m, sample_no, layer,
           ni_pct, co_pct, fe_pct, mgo_pct, sio2_pct, extra,
           sample_type, batch_id, lab, certificate_no, crm_name, crm_element, crm_expected,
           duplicate_type, duplicate_of_sample_no, source_type, source_file, remarks, is_deleted,
           created_at, updated_at, server_updated_at,
           lab_seq, client_ref, received_date, tested_date, reported_date
    from public.exp_assay
    where hole_id is not null;
  grant select on hub_export.assay to hub_reader;
end
$exp$;

-- check: select column_name from information_schema.columns where table_name = 'exp_assay' and column_name in ('lab_seq','client_ref','received_date','tested_date','reported_date');
-- check: select crm_name, analyte, certified_value, sd from public.exp_crm order by analyte;
